import{_ as s,o as e,c as n,a2 as t}from"./chunks/framework.BeV4qZ1B.js";const g=JSON.parse('{"title":"CLI Reference — BabelFHIR-TS","description":"Complete reference for the babelfhir-ts CLI — all commands, flags, supported input types, output options, caching, and registry configuration.","frontmatter":{"title":"CLI Reference — BabelFHIR-TS","description":"Complete reference for the babelfhir-ts CLI — all commands, flags, supported input types, output options, caching, and registry configuration.","head":[["link",{"rel":"canonical","href":"https://babelfhir-ts.github.io/parity-report/docs/cli-reference.html"}],["meta",{"name":"description","content":"Complete reference for the babelfhir-ts CLI — all commands, flags, supported input types, output options, caching, and registry configuration."}],["meta",{"property":"og:description","content":"Complete reference for the babelfhir-ts CLI — all commands, flags, supported input types, output options, caching, and registry configuration."}],["meta",{"name":"twitter:description","content":"Complete reference for the babelfhir-ts CLI — all commands, flags, supported input types, output options, caching, and registry configuration."}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"TechArticle\\",\\"@id\\":\\"https://babelfhir-ts.github.io/parity-report/docs/cli-reference.html#article\\",\\"headline\\":\\"CLI Reference — BabelFHIR-TS\\",\\"description\\":\\"Complete reference for the babelfhir-ts CLI — all commands, flags, supported input types, output options, caching, and registry configuration.\\",\\"url\\":\\"https://babelfhir-ts.github.io/parity-report/docs/cli-reference.html\\",\\"inLanguage\\":\\"en-US\\",\\"isPartOf\\":{\\"@id\\":\\"https://babelfhir-ts.github.io/parity-report/docs/#website\\"},\\"about\\":{\\"@id\\":\\"https://github.com/babelfhir-ts/BabelFHIR-TS#app\\"},\\"author\\":{\\"@type\\":\\"Person\\",\\"name\\":\\"Maximilian Nussbaumer\\"},\\"publisher\\":{\\"@type\\":\\"Person\\",\\"name\\":\\"Maximilian Nussbaumer\\"},\\"license\\":\\"https://opensource.org/licenses/ISC\\",\\"proficiencyLevel\\":\\"Expert\\",\\"dateModified\\":\\"2026-09-30T14:31:01.000Z\\"}"]]},"headers":[],"relativePath":"cli-reference.md","filePath":"cli-reference.md","lastUpdated":1790778661000}'),p={name:"cli-reference.md"};function i(l,a,r,o,c,d){return e(),n("div",null,[...a[0]||(a[0]=[t(`<div style="display:none;" hidden data-nosnippet>Are you an LLM? You can read better optimized documentation at /parity-report/docs/cli-reference.md for this page in Markdown format</div><h1 id="cli-reference" tabindex="-1">CLI Reference <a class="header-anchor" href="#cli-reference" aria-label="Permalink to &quot;CLI Reference&quot;">​</a></h1><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>BabelFHIR-TS: Generate TypeScript interfaces from FHIR StructureDefinitions</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Usage:</span></span>
<span class="line"><span>  babelfhir-ts [options] [&lt;input&gt; [output]]</span></span>
<span class="line"><span>  babelfhir-ts install [--package] &lt;pkg[@version]|path&gt; [--registry &lt;url&gt;] [options]</span></span>
<span class="line"><span>  babelfhir-ts update [&lt;pkg@version&gt;] [--recursive] [options]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Arguments:</span></span>
<span class="line"><span>  input   Input can be:</span></span>
<span class="line"><span>          - Canonical URL of a FHIR profile (http://... or https://...)</span></span>
<span class="line"><span>          - Directory containing FHIR packages (.tgz/.zip files)</span></span>
<span class="line"><span>          - Single FHIR package (.tgz/.zip file)</span></span>
<span class="line"><span>          - Single StructureDefinition (.json file)</span></span>
<span class="line"><span>          - Directory containing StructureDefinition files</span></span>
<span class="line"><span>  output  Output directory or archive name (optional)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Commands:</span></span>
<span class="line"><span>  install                Download, process, and npm install package as dependency</span></span>
<span class="line"><span>  update                 Regenerate all installed packages (or a specific one) with current babelfhir-ts</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Options:</span></span>
<span class="line"><span>  -h, --help               Show this help message</span></span>
<span class="line"><span>  -v, --version            Show version number</span></span>
<span class="line"><span>  --log &lt;dest&gt;             Log destination: console (default) or file</span></span>
<span class="line"><span>  --log-level &lt;level&gt;      Log verbosity: error, warn, info (default), or debug</span></span>
<span class="line"><span>  --cache-dir &lt;path&gt;       Custom cache directory (default: ~/.fhir/packages for FHIR packages, .cache for working files)</span></span>
<span class="line"><span>  --no-cache               Delete .cache working folder after generation (does not affect shared ~/.fhir/packages)</span></span>
<span class="line"><span>  --no-classes             Only generate interfaces and types (skip class generation)</span></span>
<span class="line"><span>  --no-client              Skip FHIR client generation (client generated by default)</span></span>
<span class="line"><span>  --schema &lt;format&gt;        Generate schema files alongside outputs (supported: zod)</span></span>
<span class="line"><span>  --zod-invariants         Emit FHIRPath invariants into Zod schemas (fuller checking, slower parse)</span></span>
<span class="line"><span>  --dicomweb               Generate DICOMweb helpers typed to ImagingStudy profiles in the IG</span></span>
<span class="line"><span>  --prefab                 Generate Prefab UI render functions per profile (@maxhealth.tech/prefab)</span></span>
<span class="line"><span>  --prefab-styles &lt;path&gt;   Path to styles module (.ts/.js) copied into the generated prefab/ folder</span></span>
<span class="line"><span>  --recursive              (update only) Recursively search subdirectories for lib/ folders</span></span>
<span class="line"><span>  --force                  (update only) Force regeneration even if version and flags haven&#39;t changed</span></span>
<span class="line"><span>  --skip-install           (install/update) Write the tarball without running a package manager install</span></span>
<span class="line"><span>  --outDir &lt;dir&gt;           Output directory (alias for second positional argument)</span></span>
<span class="line"><span>  --fhir-version &lt;ver&gt;     FHIR version to target: r4, r4b, or r5 (auto-detected from package if omitted)</span></span>
<span class="line"><span>  --package &lt;pkg[@version]&gt;  Download FHIR package from registry and process it (latest if no version)</span></span>
<span class="line"><span>  --registry &lt;url&gt;         FHIR package registry URL (default: https://packages.simplifier.net)</span></span>
<span class="line"><span>  --tx-server &lt;url&gt;        Terminology server URL for ValueSet expansion (e.g., https://tx.fhir.org/r4)</span></span>
<span class="line"><span>                           When set, expands ValueSets without explicit codes using $expand operation</span></span>
<span class="line"><span>  --display-language &lt;lang&gt; BCP-47 language(s) for display terms (e.g., de or de,fr,en).</span></span>
<span class="line"><span>                           Single value replaces concept displays. Comma-separated values</span></span>
<span class="line"><span>                           also generate a multi-language display map with getDisplay() helper.</span></span>
<span class="line"><span>  --max-codes &lt;n&gt;          Max concepts kept per expanded ValueSet (default: 100).</span></span>
<span class="line"><span>                           Sent as the $expand count; a larger ValueSet is truncated to it.</span></span>
<span class="line"><span>  --union-threshold &lt;n&gt;    Cap the concepts for which a ValueSet Code type is a</span></span>
<span class="line"><span>                           string-literal union. Uncapped by default; above a cap</span></span>
<span class="line"><span>                           the type is &quot;string&quot;. For a pathological IG only.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Examples:</span></span>
<span class="line"><span>  babelfhir-ts                                             # Process ./input to ./output</span></span>
<span class="line"><span>  babelfhir-ts http://hl7.org/fhir/us/core/StructureDefinition/us-core-patient  # Generate from profile URL</span></span>
<span class="line"><span>  babelfhir-ts package.tgz                                 # Process package to current directory</span></span>
<span class="line"><span>  babelfhir-ts package.tgz modified-package.tgz            # Embed interfaces in package</span></span>
<span class="line"><span>  babelfhir-ts profiles/ generated/                        # Process directory to directory</span></span>
<span class="line"><span>  babelfhir-ts --package hl7.fhir.us.core@8.0.0            # Download and process from default registry</span></span>
<span class="line"><span>  babelfhir-ts --package hl7.fhir.us.core@8.0.0 output/    # Download and output to directory</span></span>
<span class="line"><span>  babelfhir-ts --package pkg@version --log console --log-level debug  # With verbose logging</span></span>
<span class="line"><span>  babelfhir-ts install de.gematik.isik-basismodul                           # Download latest, process, and install</span></span>
<span class="line"><span>  babelfhir-ts install de.gematik.isik-basismodul@3.1.0                   # Download specific version</span></span>
<span class="line"><span>  babelfhir-ts install ./package.tgz                                      # Install from local package file</span></span>
<span class="line"><span>  babelfhir-ts install hl7.fhir.us.core@8.0.0 --registry &lt;url&gt;            # Install from custom registry</span></span>
<span class="line"><span>  babelfhir-ts install --package hl7.fhir.us.core@8.0.0 --registry &lt;url&gt;  # Alternative syntax</span></span>
<span class="line"><span>  babelfhir-ts update                                                      # Regenerate all packages in ./lib</span></span>
<span class="line"><span>  babelfhir-ts update hl7.fhir.us.core@8.0.0                               # Regenerate a specific package</span></span>
<span class="line"><span>  babelfhir-ts update --recursive                                          # Regenerate packages in all subdirectories</span></span></code></pre></div><h2 id="supported-inputs" tabindex="-1">Supported Inputs <a class="header-anchor" href="#supported-inputs" aria-label="Permalink to &quot;Supported Inputs&quot;">​</a></h2><ul><li><strong>Directory</strong> — scan all <code>.tgz</code>, <code>.zip</code>, or <code>.json</code> files inside the folder</li><li><strong>Archive</strong> — process a FHIR NPM package in <code>.tgz</code> or <code>.zip</code> format</li><li><strong>StructureDefinition JSON</strong> — generate code for a single profile definition</li><li><strong>Canonical URL</strong> — fetch a profile by URL and generate code from it</li></ul><h2 id="caching" tabindex="-1">Caching <a class="header-anchor" href="#caching" aria-label="Permalink to &quot;Caching&quot;">​</a></h2><p>The generator caches downloaded StructureDefinitions and packages inside <code>.cache/</code>. When you need a clean run, pass <code>--no-cache</code> or manually remove the folder. Temporary downloads land in <code>.temp-*</code> directories and are cleaned up automatically.</p><p>The cache directory can be customized with <code>--cache-dir &lt;path&gt;</code> or the <code>FHIR_CACHE_ROOT</code> environment variable.</p><h2 id="install-command" tabindex="-1">Install Command <a class="header-anchor" href="#install-command" aria-label="Permalink to &quot;Install Command&quot;">​</a></h2><p><code>babelfhir-ts install</code> downloads a FHIR package, generates TypeScript code, compiles it, and installs it as a local dependency in your project:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">babelfhir-ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hl7.fhir.us.core@8.0.0</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">babelfhir-ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./local-package.tgz</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">babelfhir-ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> de.gematik.isik-basismodul</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # latest version</span></span></code></pre></div><p>The install command:</p><ol><li>Downloads the package (or reads from a local path)</li><li>Generates interfaces, validators, classes, and client</li><li>Compiles to JavaScript + <code>.d.ts</code> declarations</li><li>Packs the output into a <code>.tgz</code> in your project&#39;s <code>lib/</code> folder</li><li>Runs <code>npm install</code> (or <code>bun add</code>, <code>pnpm add</code> — auto-detected) to add the dependency</li></ol><h3 id="package-manager-detection" tabindex="-1">Package Manager Detection <a class="header-anchor" href="#package-manager-detection" aria-label="Permalink to &quot;Package Manager Detection&quot;">​</a></h3><p>The install command auto-detects your package manager by checking for lockfiles:</p><table tabindex="0"><thead><tr><th>Lockfile</th><th>Manager Used</th></tr></thead><tbody><tr><td><code>bun.lockb</code> / <code>bun.lock</code></td><td><code>bun add</code></td></tr><tr><td><code>pnpm-lock.yaml</code></td><td><code>pnpm add</code></td></tr><tr><td><code>package-lock.json</code></td><td><code>npm install</code></td></tr></tbody></table><p>In monorepos, it walks up the directory tree to find the nearest lockfile.</p><h3 id="bun-compatibility" tabindex="-1">Bun Compatibility <a class="header-anchor" href="#bun-compatibility" aria-label="Permalink to &quot;Bun Compatibility&quot;">​</a></h3><p>When using Bun, the install command automatically patches <code>bun.lock</code> integrity hashes after installation to work around Bun&#39;s strict hash checking for local <code>.tgz</code> dependencies.</p><h2 id="update-command" tabindex="-1">Update Command <a class="header-anchor" href="#update-command" aria-label="Permalink to &quot;Update Command&quot;">​</a></h2><p><code>babelfhir-ts update</code> regenerates all previously installed packages with the current version of BabelFHIR-TS:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">babelfhir-ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                              # Regenerate all packages in ./lib</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">babelfhir-ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --force</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                       # Regenerate even if already up to date</span></span></code></pre></div><h3 id="smart-skip-up-to-date-detection" tabindex="-1">Smart Skip (Up-to-Date Detection) <a class="header-anchor" href="#smart-skip-up-to-date-detection" aria-label="Permalink to &quot;Smart Skip (Up-to-Date Detection)&quot;">​</a></h3><p>The update command checks whether each package was already generated with the <strong>same babelfhir-ts version</strong> and <strong>same generation flags</strong>. If nothing has changed, the package is skipped:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ babelfhir-ts update</span></span>
<span class="line"><span>Found 2 packages to update:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  hl7.fhir.us.davinci-dtr@2.1.0  →  lib/hl7.fhir.us.davinci-dtr-generated.tgz</span></span>
<span class="line"><span>  hl7.fhir.us.davinci-pas@2.0.1  →  lib/hl7.fhir.us.davinci-pas-generated.tgz</span></span>
<span class="line"><span></span></span>
<span class="line"><span>✓ hl7.fhir.us.davinci-dtr@2.1.0 — already up to date (babelfhir-ts 1.4.2)</span></span>
<span class="line"><span>✓ hl7.fhir.us.davinci-pas@2.0.1 — already up to date (babelfhir-ts 1.4.2)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>✓ 2 packages already up to date</span></span>
<span class="line"><span>  Use --force to regenerate anyway.</span></span></code></pre></div><p>A package is considered <strong>up to date</strong> when:</p><ul><li>The stored <code>babelfhir-ts</code> version (major.minor.patch) matches the currently running version</li><li>No CLI flags were passed that differ from the stored generation settings</li></ul><p>A package is <strong>always regenerated</strong> when:</p><ul><li>It was generated with an older babelfhir-ts version</li><li>A CLI flag is explicitly passed that differs from the stored value (e.g. <code>--tx-server</code> changed)</li><li>The <code>--force</code> flag is used</li><li>No version metadata is stored (packages generated before this feature)elfhir-ts update hl7.fhir.us.core@8.0.0 # Regenerate a specific package babelfhir-ts update --recursive # Search subdirectories for lib/ folders babelfhir-ts update --force # Regenerate even if already up to date</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>### Smart Skip (Up-to-Date Detection)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>The update command checks whether each package was already generated with the **same babelfhir-ts version** and **same generation flags**. If nothing has changed, the package is skipped:</span></span></code></pre></div><p>$ babelfhir-ts update Found 2 packages to update:</p><p>hl7.fhir.us.davinci-dtr@2.1.0 → lib/hl7.fhir.us.davinci-dtr-generated.tgz hl7.fhir.us.davinci-pas@2.0.1 → lib/hl7.fhir.us.davinci-pas-generated.tgz</p><p>✓ hl7.fhir.us.davinci-dtr@2.1.0 — already up to date (babelfhir-ts 1.4.2) ✓ hl7.fhir.us.davinci-pas@2.0.1 — already up to date (babelfhir-ts 1.4.2)</p><p>✓ 2 packages already up to date Use --force to regenerate anyway.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>A package is considered **up to date** when:</span></span>
<span class="line"><span>- The stored \`babelfhir-ts\` version (major.minor.patch) matches the currently running version</span></span>
<span class="line"><span>- No CLI flags were passed that differ from the stored generation settings</span></span>
<span class="line"><span></span></span>
<span class="line"><span>A package is **always regenerated** when:</span></span>
<span class="line"><span>- It was generated with an older babelfhir-ts version</span></span>
<span class="line"><span>- A CLI flag is explicitly passed that differs from the stored value (e.g. \`--tx-server\` changed)</span></span>
<span class="line"><span>- The \`--force\` flag is used</span></span>
<span class="line"><span>- No version metadata is stored (packages generated before this feature)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Settings Preservation</span></span>
<span class="line"><span></span></span>
<span class="line"><span>The update command reads the \`fhir\` metadata block from each generated package&#39;s \`package.json\` (see [Package Metadata](./generated-code#package-metadata)) and reuses the original generation settings:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- \`--tx-server\` — terminology server URL</span></span>
<span class="line"><span>- \`--display-language\` — language(s) for display terms</span></span>
<span class="line"><span>- \`--max-codes\` — cap on concepts per expanded ValueSet</span></span>
<span class="line"><span>- \`--fhir-version\` — target FHIR version</span></span>
<span class="line"><span>- \`--dicomweb\` — DICOMweb helper generation</span></span>
<span class="line"><span>- \`--no-client\` — client generation flag</span></span>
<span class="line"><span>- \`--no-classes\` — class generation flag</span></span>
<span class="line"><span>- \`--schema\` — schema format</span></span>
<span class="line"><span></span></span>
<span class="line"><span>You can override any saved setting by passing the flag explicitly on the command line.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Install Redirect</span></span>
<span class="line"><span></span></span>
<span class="line"><span>If you run \`babelfhir-ts update &lt;pkg&gt;\` for a package that isn&#39;t installed yet, it will prompt you to install it instead.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Dependency Resolution</span></span>
<span class="line"><span></span></span>
<span class="line"><span>When processing a FHIR package, BabelFHIR-TS automatically downloads transitive dependency packages listed in the IG&#39;s \`package.json\`. Dependencies are fetched from two registries in fallback order:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. [Simplifier](https://packages.simplifier.net) (default)</span></span>
<span class="line"><span>2. [FHIR Package Registry](https://packages2.fhir.org/packages)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Use \`--registry &lt;url&gt;\` to set a custom primary registry.</span></span></code></pre></div>`,35)])])}const u=s(p,[["render",i]]);export{g as __pageData,u as default};
